        Estudiantes,
        Coordinadores,
        Programas,
        Notas.Select(n => n.Notas.Codigo).Distinct().ToList());

    public IReadOnlyList<NotasAsignatura> NotasDe(string estudianteId) =>
        Notas.Where(n => n.EstudianteId == estudianteId).Select(n => n.Notas).ToList();

