{
    using var fabrica = new FabricaApi(llm: GuionesLlm.SinHerramientas(_ => $"{respuesta} {CitasEscritas}"), conocimientoReal: true);

    var resultado = await fabrica.PreguntarEstudianteAsync("EST-001", PreguntaDefinitiva);

