public async Task ESC_162_Las_citas_de_documentos_son_solo_de_secciones_entregadas_al_llm()
{
    var propuesta = string.Join("; ", new[] { Entregada1, Entregada2, NoEntregada1, NoEntregada2 }.Select(Cita));
