        var escenario = Con(LeeElPrograma(texto), Indice(Articulo5, Articulo6, Articulo11));

        var resultado = await escenario.PreguntarAsync(Coord01, PreguntaPerdidas);

        if (correcto)
        {
            AfirmarRespondida(resultado, texto);
