        var resultado = await escenario.PreguntarAsync(Coord02, PreguntaHabilitacion);

        Assert.Empty(escenario.Api.LecturasNotas);
        AfirmarEstadoNoVerificado(resultado, escenario, usoDatos: false);
    }

    [Fact]
