const fs = require("fs");
const dir = process.argv[2];
const leer = (f) => JSON.parse(fs.readFileSync(`${dir}/${f}`, "utf8"));
const escribir = (f, datos) => fs.writeFileSync(`${dir}/${f}`, JSON.stringify(datos, null, 2) + "\n");

const NO_VERIFICABLE = "No pude verificar los datos de la respuesta. Intenta de nuevo o reformula la pregunta.";
const NEGATIVA_COORD = "No puedo compartir esa información: solo puedes consultar los datos de los estudiantes de tu programa.";
const NEGATIVA_EST = "No puedo compartir esa información: solo puedes consultar tus propios datos académicos.";
const SIN_INFO = "No encuentro esa información en los documentos disponibles.";
const ART = (n) => `reglamento_academico_2025.md · Artículo ${n}`;
const EVA = (n) => `evaluacion_y_calificaciones.md · Sección ${n}`;
const BECA = "bienestar_y_becas.md · Sección 3.1";
const NOTAS = "Datos del estudiante · Notas";
const ASIST = "Datos del estudiante · Asistencia";
const ADM = "Datos del programa · ADM";
const ING = "Datos del programa · ING-SIS";

const PERDIDAS = "¿Qué estudiantes de mi programa tienen alguna asignatura perdida?";
const PERDIDAS_ING = "¿Qué estudiantes de mi programa perdieron materias?";

function caso(id, fuente, rol, usuario, pregunta, http, texto, herramientas, extra) {
  return {
    id,
    fuente,
    usuario: { rol, id: usuario },
    pregunta,
    http,
    contiene: [],
    noContiene: [],
    citasIncluye: [],
    citasProhibidas: [],
    citasVacias: false,
    citasExactas: null,
    usoDatosEstudiante: false,
    respuestaExacta: null,
    tokensCero: false,
    filtroPrevio: false,
    requiereLlm: true,
    soloOffline: true,
    offline: { herramientas, estudianteIdCoordinador: null, texto },
    ...extra
  };
}

const sinCambios = (id, fuente, rol, usuario, pregunta, texto, herr, uso, citasExactas) =>
  caso(id, fuente, rol, usuario, pregunta, 200, texto, herr, { respuestaExacta: texto, usoDatosEstudiante: uso, citasExactas });

const noVerificable = (id, fuente, rol, usuario, pregunta, texto, herr, uso) =>
  caso(id, fuente, rol, usuario, pregunta, 200, texto, herr, { respuestaExacta: NO_VERIFICABLE, citasVacias: true, usoDatosEstudiante: uso });

const negativa = (id, fuente, rol, usuario, pregunta, texto, herr, uso) =>
  caso(id, fuente, rol, usuario, pregunta, 200, texto, herr, {
    respuestaExacta: rol === "coordinador" ? NEGATIVA_COORD : NEGATIVA_EST,
    citasExactas: [ART(22)],
    usoDatosEstudiante: uso
  });

const q10_1 = "Se aprueba una asignatura con una nota definitiva de 3.0 o más, en una escala de 0.0 a 5.0 (reglamento_academico_2025.md · Artículo 5).";
const q10_5 = "Contabilidad: 3.9. Se aprueba con una definitiva de 3.0 o más (reglamento_academico_2025.md · Artículo 5).";
const beca = [
  "Se aprueba con un promedio ponderado del periodo igual o superior a 4.3, sin asignaturas perdidas, y matriculando al menos 12 créditos (bienestar_y_becas.md · Sección 3.1).",
  "Para obtener la beca por rendimiento académico, se deben cumplir los siguientes requisitos:\n\n- Promedio ponderado del periodo igual o superior a 4.3.\n- Ninguna asignatura perdida, incluidas las perdidas por inasistencia.\n- Matrícula de al menos 12 créditos.\n\nEstos requisitos se respaldan en bienestar_y_becas.md · Sección 3.1.",
